/**
 * AppDialog — the single dialog primitive for the app.
 *
 * Every modal renders through this component (or through `ConfirmDialog`, which
 * is itself built on top of it) so close affordance, busy locking, divider
 * style, footer layout and mobile behaviour stay identical everywhere.
 *
 * For simple confirm/alert prompts, use `ConfirmDialog` instead.
 */
import * as React from 'react';
import {
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    IconButton,
    Stack,
    Typography,
    useMediaQuery,
    useTheme,
} from '@mui/material';
import CloseIcon from '@mui/icons-material/Close';

export type AppDialogWidth = 'xs' | 'sm' | 'md' | 'lg' | 'xl';

export interface AppDialogProps {
    open: boolean;
    onClose: () => void;
    /** Primary heading. Plain text is preferred so sizing stays uniform. */
    title: React.ReactNode;
    /** Secondary line under the title — e.g. the member a dialog acts on. */
    subtitle?: React.ReactNode;
    /** Icon rendered before the title. */
    titleIcon?: React.ReactNode;
    /** Extra controls in the title row, placed left of the close button. */
    titleActions?: React.ReactNode;
    /** Rendered below the title row but still inside the header (steppers). */
    titleContent?: React.ReactNode;
    /** Content rendered inside DialogContent. */
    children: React.ReactNode;
    /**
     * Optional footer. Convention: cancel/dismiss buttons use `color="inherit"`,
     * the primary action uses `variant="contained"`. Button height and type scale
     * are pinned here, so call sites should not set `size`.
     */
    actions?: React.ReactNode;
    /** Dialog max width — defaults to 'sm'. */
    maxWidth?: AppDialogWidth;
    /** Lock the dialog (close icon, escape and backdrop ignored). */
    busy?: boolean;
    /** Disable padding on DialogContent (for full-bleed media). */
    disablePadding?: boolean;
    /**
     * Draw rules between header/content/footer. Defaults to true when the
     * dialog has a footer, which is where the separation actually helps.
     */
    dividers?: boolean;
    /**
     * Expand to full screen on phones. Defaults to true for 'md' and wider,
     * since those cannot fit a phone viewport as a floating card.
     */
    fullScreenOnMobile?: boolean;
    /** Prevent backdrop/escape dismissal even when not busy. */
    disableBackdropClose?: boolean;
    'aria-labelledby'?: string;
    'aria-describedby'?: string;
}

const WIDE: AppDialogWidth[] = ['md', 'lg', 'xl'];

export const AppDialog: React.FC<AppDialogProps> = ({
    open,
    onClose,
    title,
    subtitle,
    titleIcon,
    titleActions,
    titleContent,
    children,
    actions,
    maxWidth = 'sm',
    busy = false,
    disablePadding = false,
    dividers,
    fullScreenOnMobile,
    disableBackdropClose = false,
    'aria-labelledby': ariaLabelledBy,
    'aria-describedby': ariaDescribedBy,
}) => {
    const theme = useTheme();
    const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

    const goFullScreen = (fullScreenOnMobile ?? WIDE.includes(maxWidth)) && isMobile;
    const showDividers = dividers ?? !!actions;
    const locked = busy || disableBackdropClose;

    const handleClose = () => {
        if (!locked) onClose();
    };

    return (
        <Dialog
            open={open}
            onClose={handleClose}
            maxWidth={maxWidth}
            fullWidth
            fullScreen={goFullScreen}
            aria-labelledby={ariaLabelledBy}
            aria-describedby={ariaDescribedBy}
        >
            <DialogTitle id={ariaLabelledBy} component="div">
                <Stack direction="row" spacing={1} sx={{ alignItems: 'center', minWidth: 0 }}>
                    {titleIcon}
                    <Stack sx={{ minWidth: 0, flexGrow: 1 }}>
                        <Typography component="h2" variant="h6" sx={{ lineHeight: 1.3 }}>
                            {title}
                        </Typography>
                        {subtitle && (
                            <Typography variant="body2" sx={{ color: 'text.secondary' }}>
                                {subtitle}
                            </Typography>
                        )}
                    </Stack>
                    <Stack direction="row" spacing={0.5} sx={{ alignItems: 'center', flexShrink: 0 }}>
                        {titleActions}
                        <IconButton
                            aria-label="Close"
                            onClick={onClose}
                            disabled={busy}
                            size="small"
                        >
                            <CloseIcon fontSize="small" />
                        </IconButton>
                    </Stack>
                </Stack>
                {titleContent}
            </DialogTitle>

            <DialogContent dividers={showDividers} sx={disablePadding ? { p: 0 } : undefined}>
                {children}
            </DialogContent>

            {actions && (
                <DialogActions
                    sx={{
                        px: 3,
                        py: 2,
                        // Pin footer buttons to the medium height/type scale so a stray
                        // size prop in one dialog cannot drift from the rest. Horizontal
                        // padding is left to the variant (text buttons sit tighter).
                        '& .MuiButton-root': { fontSize: '0.875rem', py: 0.75 },
                    }}
                >
                    {actions}
                </DialogActions>
            )}
        </Dialog>
    );
};

export default AppDialog;
